INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('product-led-channel-letters','product','led-channel-letters','{"title": "LED Channel Letters", "intro": "Give your business name or logo an illuminated presence. Share the look you want, and we’ll review the letter construction, face material and lighting requirements for your project.", "body": "**按钮**：Get a Quote for LED Letters\n\n**图片区标题**：Explore the Face, Edges and Lighting\n\nView examples of illuminated lettering and construction details. The final appearance depends on the selected materials, letter size and lighting arrangement.\n\n**定制区标题**：Built Around Your Lettering\n\nDiscuss your logo or font, overall dimensions, face colour, side finish, lighting colour and mounting requirements.\n\n**应用区标题**：Plan for the Installation Location\n\nTell us where the letters will be used, the mounting surface and whether the location is indoors or outdoors. These details help define what must be reviewed before quoting.\n\n**Are these letters suitable for outdoor use?**\n\nOutdoor suitability must be confirmed for the specific construction, electrical components and installation conditions.\n\n**Can you match my brand colours?**\n\nShare your colour references. Available finishes and the appearance when illuminated need to be reviewed before confirmation.\n\n**结尾标题**：Looking for This Style in Your Own Logo?\n\nSend us your project details and continue the discussion on WhatsApp.\n\n**按钮**：Discuss My LED Sign", "image": "/assets/frontlit-form.webp", "imageAlt": "LED Channel Letters illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept from approved UI", "indexable": true, "sort": 0, "seedIndex": 0}','{"title": "LED Channel Letters", "intro": "Give your business name or logo an illuminated presence. Share the look you want, and we’ll review the letter construction, face material and lighting requirements for your project.", "body": "**按钮**：Get a Quote for LED Letters\n\n**图片区标题**：Explore the Face, Edges and Lighting\n\nView examples of illuminated lettering and construction details. The final appearance depends on the selected materials, letter size and lighting arrangement.\n\n**定制区标题**：Built Around Your Lettering\n\nDiscuss your logo or font, overall dimensions, face colour, side finish, lighting colour and mounting requirements.\n\n**应用区标题**：Plan for the Installation Location\n\nTell us where the letters will be used, the mounting surface and whether the location is indoors or outdoors. These details help define what must be reviewed before quoting.\n\n**Are these letters suitable for outdoor use?**\n\nOutdoor suitability must be confirmed for the specific construction, electrical components and installation conditions.\n\n**Can you match my brand colours?**\n\nShare your colour references. Available finishes and the appearance when illuminated need to be reviewed before confirmation.\n\n**结尾标题**：Looking for This Style in Your Own Logo?\n\nSend us your project details and continue the discussion on WhatsApp.\n\n**按钮**：Discuss My LED Sign", "image": "/assets/frontlit-form.webp", "imageAlt": "LED Channel Letters illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept from approved UI", "indexable": true, "sort": 0, "seedIndex": 0}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('product-backlit-letters','product','backlit-letters','{"title": "Backlit & Halo Lit Letters", "intro": "Create a glow behind your logo or lettering. Explore backlit sign examples, then discuss the finish, lighting and mounting arrangement for your space.", "body": "**按钮**：Get a Quote for Backlit Letters\n\n**效果区标题**：The Light Behind the Letters\n\nBacklighting creates an illuminated outline on the surface behind the sign. The result is influenced by the letter shape, wall colour, surface texture and distance from the wall.\n\n**定制区标题**：Choose the Finish. Review the Glow.\n\nDiscuss metal or other available face finishes, lettering dimensions, light colour and mounting details. Materials and construction are confirmed against the selected design.\n\n**准备资料标题**：Show Us Where It Will Go\n\nA photo of the installation area can help us understand the background and layout. Approximate dimensions are enough to begin the conversation.\n\n**Will the glow look exactly like the reference photo?**\n\nThe surrounding light, wall surface and installation spacing affect the appearance. Reference images show a direction; the final setup needs project-specific review.\n\n**结尾标题**：Explore a Backlit Version of Your Logo\n\n**按钮**：Discuss My Backlit Sign", "image": "/assets/office-halo.webp", "imageAlt": "Backlit & Halo Lit Letters illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept from approved UI", "indexable": true, "sort": 1, "seedIndex": 1}','{"title": "Backlit & Halo Lit Letters", "intro": "Create a glow behind your logo or lettering. Explore backlit sign examples, then discuss the finish, lighting and mounting arrangement for your space.", "body": "**按钮**：Get a Quote for Backlit Letters\n\n**效果区标题**：The Light Behind the Letters\n\nBacklighting creates an illuminated outline on the surface behind the sign. The result is influenced by the letter shape, wall colour, surface texture and distance from the wall.\n\n**定制区标题**：Choose the Finish. Review the Glow.\n\nDiscuss metal or other available face finishes, lettering dimensions, light colour and mounting details. Materials and construction are confirmed against the selected design.\n\n**准备资料标题**：Show Us Where It Will Go\n\nA photo of the installation area can help us understand the background and layout. Approximate dimensions are enough to begin the conversation.\n\n**Will the glow look exactly like the reference photo?**\n\nThe surrounding light, wall surface and installation spacing affect the appearance. Reference images show a direction; the final setup needs project-specific review.\n\n**结尾标题**：Explore a Backlit Version of Your Logo\n\n**按钮**：Discuss My Backlit Sign", "image": "/assets/office-halo.webp", "imageAlt": "Backlit & Halo Lit Letters illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept from approved UI", "indexable": true, "sort": 1, "seedIndex": 1}','published',1);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('product-metal-letters','product','metal-letters','{"title": "Metal & Dimensional Letters", "intro": "Give your logo depth through raised lettering and considered surface details. Explore metal lettering examples and discuss the finish and construction that suit your project.", "body": "**按钮**：Get a Quote for Metal Letters\n\n**细节区标题**：A Closer Look at the Finish\n\nCompare examples of brushed, polished, painted and plated appearances. Available materials and finish processes depend on the design and intended use.\n\n**定制区标题**：Define the Shape and Depth\n\nShare your artwork, dimensions, preferred depth, surface appearance and mounting needs. We’ll review the fabrication approach before confirming the specification.\n\n**说明标题**：Illuminated or Non-illuminated?\n\nMetal lettering can involve different constructions. Tell us whether you want a non-illuminated sign or a lighting effect so the right options can be reviewed.\n\n**Can I choose a metallic colour from a photo?**\n\nA reference photo is a useful starting point. For an exact finish requirement, we’ll need to confirm the available process and how the finish will be approved.\n\n**结尾标题**：Let’s Review Your Metal Lettering Project\n\n**按钮**：Discuss My Metal Letters", "image": "/assets/metal-studio-portrait.webp", "imageAlt": "Metal & Dimensional Letters illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept from approved UI", "indexable": true, "sort": 2, "seedIndex": 2}','{"title": "Metal & Dimensional Letters", "intro": "Give your logo depth through raised lettering and considered surface details. Explore metal lettering examples and discuss the finish and construction that suit your project.", "body": "**按钮**：Get a Quote for Metal Letters\n\n**细节区标题**：A Closer Look at the Finish\n\nCompare examples of brushed, polished, painted and plated appearances. Available materials and finish processes depend on the design and intended use.\n\n**定制区标题**：Define the Shape and Depth\n\nShare your artwork, dimensions, preferred depth, surface appearance and mounting needs. We’ll review the fabrication approach before confirming the specification.\n\n**说明标题**：Illuminated or Non-illuminated?\n\nMetal lettering can involve different constructions. Tell us whether you want a non-illuminated sign or a lighting effect so the right options can be reviewed.\n\n**Can I choose a metallic colour from a photo?**\n\nA reference photo is a useful starting point. For an exact finish requirement, we’ll need to confirm the available process and how the finish will be approved.\n\n**结尾标题**：Let’s Review Your Metal Lettering Project\n\n**按钮**：Discuss My Metal Letters", "image": "/assets/metal-studio-portrait.webp", "imageAlt": "Metal & Dimensional Letters illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept from approved UI", "indexable": true, "sort": 2, "seedIndex": 2}','published',2);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('product-acrylic-letters','product','acrylic-letters','{"title": "Acrylic Letters & Signs", "intro": "Explore acrylic lettering, logo shapes and layered sign designs. Share the colour, depth and overall appearance you have in mind.", "body": "**按钮**：Get a Quote for Acrylic Signs\n\n**细节区标题**：Colour, Depth and Layering\n\nAcrylic can be used in different lettering and sign constructions. View the examples to compare material appearance, edge details and layered effects.\n\n**定制区标题**：Start with Your Artwork\n\nDiscuss cut shapes, dimensions, material colour, thickness, layers and fixing requirements. Availability and suitability are confirmed for each design.\n\n**Are acrylic letters always illuminated?**\n\nNo. Acrylic may be used in non-illuminated lettering or as part of an illuminated construction. Tell us which effect you want.\n\n**结尾标题**：Have an Acrylic Logo Sign in Mind?\n\n**按钮**：Discuss My Acrylic Sign", "image": "/assets/acrylic-sign.webp", "imageAlt": "Acrylic Letters & Signs illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept from approved UI", "indexable": true, "sort": 3, "seedIndex": 3}','{"title": "Acrylic Letters & Signs", "intro": "Explore acrylic lettering, logo shapes and layered sign designs. Share the colour, depth and overall appearance you have in mind.", "body": "**按钮**：Get a Quote for Acrylic Signs\n\n**细节区标题**：Colour, Depth and Layering\n\nAcrylic can be used in different lettering and sign constructions. View the examples to compare material appearance, edge details and layered effects.\n\n**定制区标题**：Start with Your Artwork\n\nDiscuss cut shapes, dimensions, material colour, thickness, layers and fixing requirements. Availability and suitability are confirmed for each design.\n\n**Are acrylic letters always illuminated?**\n\nNo. Acrylic may be used in non-illuminated lettering or as part of an illuminated construction. Tell us which effect you want.\n\n**结尾标题**：Have an Acrylic Logo Sign in Mind?\n\n**按钮**：Discuss My Acrylic Sign", "image": "/assets/acrylic-sign.webp", "imageAlt": "Acrylic Letters & Signs illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept from approved UI", "indexable": true, "sort": 3, "seedIndex": 3}','published',3);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('product-lightbox-neon','product','lightbox-neon','{"title": "Lightboxes & Neon-style Signs", "intro": "Explore illuminated sign faces and line-based lighting effects. Choose the direction you like, then discuss the construction and details for your project.", "body": "**按钮**：Get a Quote for This Style\n\n**Lightbox Signs**\n\nExplore examples with an illuminated face or panel. Share the overall shape, artwork, dimensions and intended location so the sign construction can be reviewed.\n\n**Neon-style Signs**\n\nExplore illuminated lines, lettering and graphic shapes. The light source, backing and construction must be confirmed for the selected product.\n\n**重要说明**：“Neon-style” describes the visual direction on this page. Confirm the actual light source and materials with us before ordering.\n\n**Can you make my logo in this style?**\n\nSend the artwork for review. Fine details, line spacing and the required size may affect how the design can be produced.\n\n**结尾标题**：Which Lighting Effect Fits Your Idea?\n\n**按钮**：Discuss My Lightbox or Neon-style Sign", "image": "/assets/lightbox-sign.webp", "imageAlt": "Lightboxes & Neon-style Signs illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept from approved UI", "indexable": true, "sort": 4, "seedIndex": 4}','{"title": "Lightboxes & Neon-style Signs", "intro": "Explore illuminated sign faces and line-based lighting effects. Choose the direction you like, then discuss the construction and details for your project.", "body": "**按钮**：Get a Quote for This Style\n\n**Lightbox Signs**\n\nExplore examples with an illuminated face or panel. Share the overall shape, artwork, dimensions and intended location so the sign construction can be reviewed.\n\n**Neon-style Signs**\n\nExplore illuminated lines, lettering and graphic shapes. The light source, backing and construction must be confirmed for the selected product.\n\n**重要说明**：“Neon-style” describes the visual direction on this page. Confirm the actual light source and materials with us before ordering.\n\n**Can you make my logo in this style?**\n\nSend the artwork for review. Fine details, line spacing and the required size may affect how the design can be produced.\n\n**结尾标题**：Which Lighting Effect Fits Your Idea?\n\n**按钮**：Discuss My Lightbox or Neon-style Sign", "image": "/assets/lightbox-sign.webp", "imageAlt": "Lightboxes & Neon-style Signs illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept from approved UI", "indexable": true, "sort": 4, "seedIndex": 4}','published',4);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('product-specialty-signs','product','specialty-signs','{"title": "Specialty Custom Signs", "intro": "Have a sign idea that goes beyond a standard look? Share the effect, finish or construction you are trying to achieve.", "body": "**按钮**：Discuss a Custom Fabrication Project\n\n**展示区标题**：Explore Different Fabrication Directions\n\nSelected examples may include exposed-light effects, compact lettering, colour-changing illumination and distinctive surface treatments. Each option requires its own specification review.\n\n实施说明：仅展示已核实的具体工艺。\n\n**定制区标题**：Bring the Reference. Let’s Review the Details.\n\nSend a sketch, artwork or reference image. We’ll discuss what can be produced, what needs further checking and which details are required for a quote.\n\n**Can you reproduce a sign from a photo?**\n\nA photo helps explain the appearance you want, but may not show its materials or construction. We’ll need to clarify those details rather than assume an exact match.\n\n**结尾标题**：Tell Us What You’re Trying to Make\n\n**按钮**：Start My Project Enquiry", "image": "/assets/specialty-sign.webp", "imageAlt": "Specialty Custom Signs illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept from approved UI", "indexable": true, "sort": 5, "seedIndex": 5}','{"title": "Specialty Custom Signs", "intro": "Have a sign idea that goes beyond a standard look? Share the effect, finish or construction you are trying to achieve.", "body": "**按钮**：Discuss a Custom Fabrication Project\n\n**展示区标题**：Explore Different Fabrication Directions\n\nSelected examples may include exposed-light effects, compact lettering, colour-changing illumination and distinctive surface treatments. Each option requires its own specification review.\n\n实施说明：仅展示已核实的具体工艺。\n\n**定制区标题**：Bring the Reference. Let’s Review the Details.\n\nSend a sketch, artwork or reference image. We’ll discuss what can be produced, what needs further checking and which details are required for a quote.\n\n**Can you reproduce a sign from a photo?**\n\nA photo helps explain the appearance you want, but may not show its materials or construction. We’ll need to clarify those details rather than assume an exact match.\n\n**结尾标题**：Tell Us What You’re Trying to Make\n\n**按钮**：Start My Project Enquiry", "image": "/assets/specialty-sign.webp", "imageAlt": "Specialty Custom Signs illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept from approved UI", "indexable": true, "sort": 5, "seedIndex": 5}','published',5);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('project-office-logo-concept','project','office-logo-concept','{"title": "Office Logo Sign", "intro": "Backlit lettering in a reception setting.", "body": "This is a design concept, not a completed customer project. Final materials, dimensions, lighting and mounting details must be reviewed for your project.", "image": "/assets/office-halo.webp", "imageAlt": "Office Logo Sign illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept", "product": "backlit-letters", "setting": "Office", "indexable": false, "sort": 0}','{"title": "Office Logo Sign", "intro": "Backlit lettering in a reception setting.", "body": "This is a design concept, not a completed customer project. Final materials, dimensions, lighting and mounting details must be reviewed for your project.", "image": "/assets/office-halo.webp", "imageAlt": "Office Logo Sign illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept", "product": "backlit-letters", "setting": "Office", "indexable": false, "sort": 0}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('project-storefront-concept','project','storefront-concept','{"title": "Storefront Sign", "intro": "Illuminated lettering on a commercial facade.", "body": "This is a design concept, not a completed customer project. Final materials, dimensions, lighting and mounting details must be reviewed for your project.", "image": "/assets/storefront-wide.webp", "imageAlt": "Storefront Sign illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept", "product": "led-channel-letters", "setting": "Storefront", "indexable": false, "sort": 0}','{"title": "Storefront Sign", "intro": "Illuminated lettering on a commercial facade.", "body": "This is a design concept, not a completed customer project. Final materials, dimensions, lighting and mounting details must be reviewed for your project.", "image": "/assets/storefront-wide.webp", "imageAlt": "Storefront Sign illustrative concept", "imageKind": "concept", "sourceNote": "ImageGen concept", "product": "led-channel-letters", "setting": "Storefront", "indexable": false, "sort": 0}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('page-for-sign-companies','page','for-sign-companies','{"title": "Custom Sign Fabrication for Sign Companies & Installers", "intro": "Sourcing custom lettering or illuminated signs for a customer project? We coordinate with manufacturing partners to review your specifications and prepare a project-based supply quote.", "body": "**按钮**：Discuss a Trade Project\n\n**Support for Your Customer Projects**\n\nFor sign companies, installers, fit-out contractors and procurement teams looking for a fabrication supply partner.\n\n**Keep the Fabrication Scope Clear**\n\n**Artwork & Dimensions**\n\nShare drawings, vector artwork and the dimensions that need to be followed.\n\n**Materials & Finishes**\n\nSpecify the construction and finish, or identify the options you would like reviewed.\n\n**Lighting & Electrical Details**\n\nTell us the destination market and the requirements your project needs to meet.\n\n**Mounting & Documentation**\n\nIdentify the fixing details, drawings or other documents required by your installation team.\n\n**Packing & Delivery**\n\nConfirm quantities, destination and any handling or packing requirements.\n\n**Still Finalising the Specification?**\n\nYou can begin with a reference image or preliminary drawing. We’ll clarify the open points before treating a specification as ready for production.\n\n**From Enquiry to Production Confirmation**\n\nShare the project → Review open details → Confirm the quoted scope → Approve production requirements → Arrange fabrication and delivery\n\n**Confirm Responsibilities Before Ordering**\n\nFabrication, electrical requirements, documentation, shipping and local installation responsibilities need to be agreed for each project. Please identify any required approvals or documents at the enquiry stage.\n\n**结尾标题**：Have a Project Ready for Review?\n\nStart with the sign type, destination and project stage. Continue on WhatsApp to share drawings and discuss the details.\n\n**按钮**：Start a Trade Enquiry", "image": "/assets/craft-details.webp", "imageAlt": "Illustrative sign inspection", "imageKind": "concept", "sort": 0, "indexable": true}','{"title": "Custom Sign Fabrication for Sign Companies & Installers", "intro": "Sourcing custom lettering or illuminated signs for a customer project? We coordinate with manufacturing partners to review your specifications and prepare a project-based supply quote.", "body": "**按钮**：Discuss a Trade Project\n\n**Support for Your Customer Projects**\n\nFor sign companies, installers, fit-out contractors and procurement teams looking for a fabrication supply partner.\n\n**Keep the Fabrication Scope Clear**\n\n**Artwork & Dimensions**\n\nShare drawings, vector artwork and the dimensions that need to be followed.\n\n**Materials & Finishes**\n\nSpecify the construction and finish, or identify the options you would like reviewed.\n\n**Lighting & Electrical Details**\n\nTell us the destination market and the requirements your project needs to meet.\n\n**Mounting & Documentation**\n\nIdentify the fixing details, drawings or other documents required by your installation team.\n\n**Packing & Delivery**\n\nConfirm quantities, destination and any handling or packing requirements.\n\n**Still Finalising the Specification?**\n\nYou can begin with a reference image or preliminary drawing. We’ll clarify the open points before treating a specification as ready for production.\n\n**From Enquiry to Production Confirmation**\n\nShare the project → Review open details → Confirm the quoted scope → Approve production requirements → Arrange fabrication and delivery\n\n**Confirm Responsibilities Before Ordering**\n\nFabrication, electrical requirements, documentation, shipping and local installation responsibilities need to be agreed for each project. Please identify any required approvals or documents at the enquiry stage.\n\n**结尾标题**：Have a Project Ready for Review?\n\nStart with the sign type, destination and project stage. Continue on WhatsApp to share drawings and discuss the details.\n\n**按钮**：Start a Trade Enquiry", "image": "/assets/craft-details.webp", "imageAlt": "Illustrative sign inspection", "imageKind": "concept", "sort": 0, "indexable": true}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('page-how-it-works','page','how-it-works','{"title": "How Your Custom Sign Project Works", "intro": "Start with what you know. We’ll clarify the remaining details with you before confirming a quote and production specification.", "body": "**Step 1 — Tell Us About the Project**\n\nShare the intended use, delivery country and preferred sign style. A logo, reference photo or initial idea is enough to start the discussion.\n\n**Step 2 — Review the Design & Requirements**\n\nContinue on WhatsApp to discuss dimensions, artwork, materials, lighting, quantities and the installation location. We’ll identify what still needs to be confirmed.\n\n**Step 3 — Review Your Project Quote**\n\nYour quote is based on the agreed information. Check the specifications, included costs, delivery arrangements and any assumptions or exclusions before proceeding.\n\n**Step 4 — Confirm the Order & Production Details**\n\nArtwork, dimensions, finishes, commercial terms and the approval process must be confirmed before production is authorised.\n\n**Step 5 — Fabrication, Checks & Packing**\n\nProduction and checks follow the confirmed order requirements. Any agreed inspection records or packing requirements should be included in the project scope.\n\n**Step 6 — Shipping & Installation Preparation**\n\nShipping arrangements are confirmed for the destination. Local installation responsibilities and any required support documents should be agreed before dispatch.\n\n**Useful to Have, but Not Required to Start**\n\n- Your logo or reference image\n- Approximate dimensions\n- Indoor or outdoor location\n- Quantity\n- Delivery country and city\n- Preferred delivery timing\n\n**辅助说明**：Missing some details? Tell us what is still undecided.\n\n**按钮**：Start My Enquiry", "image": "", "imageAlt": "Illustrative sign inspection", "imageKind": "concept", "sort": 0, "indexable": true}','{"title": "How Your Custom Sign Project Works", "intro": "Start with what you know. We’ll clarify the remaining details with you before confirming a quote and production specification.", "body": "**Step 1 — Tell Us About the Project**\n\nShare the intended use, delivery country and preferred sign style. A logo, reference photo or initial idea is enough to start the discussion.\n\n**Step 2 — Review the Design & Requirements**\n\nContinue on WhatsApp to discuss dimensions, artwork, materials, lighting, quantities and the installation location. We’ll identify what still needs to be confirmed.\n\n**Step 3 — Review Your Project Quote**\n\nYour quote is based on the agreed information. Check the specifications, included costs, delivery arrangements and any assumptions or exclusions before proceeding.\n\n**Step 4 — Confirm the Order & Production Details**\n\nArtwork, dimensions, finishes, commercial terms and the approval process must be confirmed before production is authorised.\n\n**Step 5 — Fabrication, Checks & Packing**\n\nProduction and checks follow the confirmed order requirements. Any agreed inspection records or packing requirements should be included in the project scope.\n\n**Step 6 — Shipping & Installation Preparation**\n\nShipping arrangements are confirmed for the destination. Local installation responsibilities and any required support documents should be agreed before dispatch.\n\n**Useful to Have, but Not Required to Start**\n\n- Your logo or reference image\n- Approximate dimensions\n- Indoor or outdoor location\n- Quantity\n- Delivery country and city\n- Preferred delivery timing\n\n**辅助说明**：Missing some details? Tell us what is still undecided.\n\n**按钮**：Start My Enquiry", "image": "", "imageAlt": "Illustrative sign inspection", "imageKind": "concept", "sort": 0, "indexable": true}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('page-about','page','about','{"title": "Custom Signs, Through Clear Project Coordination", "intro": "Custom Sign Forge works with manufacturing partners to supply custom business signs, illuminated lettering and dimensional signs for overseas projects.", "body": "**What We Do**\n\nWe help move an enquiry from a logo or reference idea towards a defined sign specification and project quote. Our role includes customer communication and coordination with manufacturing partners around the agreed supply requirements.\n\n**How We Work with Manufacturing Partners**\n\nDifferent sign styles involve different materials and fabrication processes. We work with production partners to review the proposed construction, confirm details and coordinate the order requirements.\n\n**See the Work Behind the Sign**\n\nExplore product details, production images, lighting checks and packing examples. We distinguish between samples, finished products and documented projects so you can understand what each image shows.\n\n**Business Information**\n\nTrading name: Custom Sign Forge\n\nLegal business name: [Legal entity]\n\nBusiness location: [Verified location]\n\nEmail: [Business email]\n\nWhatsApp: [WhatsApp number]\n\n**结尾标题**：Let’s Talk About Your Sign\n\nTell us what you are planning, where it will be delivered and what you already have prepared.\n\n**按钮**：Discuss My Project", "image": "/assets/craft-details.webp", "imageAlt": "Illustrative sign inspection", "imageKind": "concept", "sort": 0, "indexable": true}','{"title": "Custom Signs, Through Clear Project Coordination", "intro": "Custom Sign Forge works with manufacturing partners to supply custom business signs, illuminated lettering and dimensional signs for overseas projects.", "body": "**What We Do**\n\nWe help move an enquiry from a logo or reference idea towards a defined sign specification and project quote. Our role includes customer communication and coordination with manufacturing partners around the agreed supply requirements.\n\n**How We Work with Manufacturing Partners**\n\nDifferent sign styles involve different materials and fabrication processes. We work with production partners to review the proposed construction, confirm details and coordinate the order requirements.\n\n**See the Work Behind the Sign**\n\nExplore product details, production images, lighting checks and packing examples. We distinguish between samples, finished products and documented projects so you can understand what each image shows.\n\n**Business Information**\n\nTrading name: Custom Sign Forge\n\nLegal business name: [Legal entity]\n\nBusiness location: [Verified location]\n\nEmail: [Business email]\n\nWhatsApp: [WhatsApp number]\n\n**结尾标题**：Let’s Talk About Your Sign\n\nTell us what you are planning, where it will be delivered and what you already have prepared.\n\n**按钮**：Discuss My Project", "image": "/assets/craft-details.webp", "imageAlt": "Illustrative sign inspection", "imageKind": "concept", "sort": 0, "indexable": true}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('landing-custom-logo-signs','landing','custom-logo-signs','{"title": "Turn Your Business Logo into a Custom Sign", "intro": "**H1**：Turn Your Business Logo into a Custom Sign", "body": "Explore illuminated and dimensional logo signs for your business space. Share your logo or a reference idea to discuss the style, specifications and quote.\n\n**按钮**：Discuss My Logo Sign\n\n**辅助文案**：Not sure about materials or dimensions? Start with what you have.\n\n**Find a Look That Fits Your Space**\n\nCompare front-lit lettering, backlit effects and non-illuminated finishes through selected product examples.\n\n**Made Around Your Logo and Location**\n\nYour artwork, dimensions, mounting surface and lighting preferences help define the sign. Final construction and suitability are reviewed before confirmation.\n\n**A Simple Way to Start**\n\nShare your project → Continue on WhatsApp → Confirm the details → Review your quote\n\n**Do I need a finished design?**\n\nNo final production drawing is required to begin. Share your logo or a reference image for review.\n\n**Can you deliver to my location?**\n\nTell us the destination so we can confirm shipping arrangements.\n\n**Is installation included?**\n\nInstallation scope is confirmed separately for your project. Tell us whether you have a local installer.\n\n**底部标题**：Let’s Explore Your Logo Sign\n\nTell us where it will be used and delivered, then continue on WhatsApp.\n\n**按钮**：Get a Custom Quote", "image": "/assets/office-halo.webp", "imageAlt": "Custom signage concept", "imageKind": "concept", "indexable": false, "sort": 0}','{"title": "Turn Your Business Logo into a Custom Sign", "intro": "**H1**：Turn Your Business Logo into a Custom Sign", "body": "Explore illuminated and dimensional logo signs for your business space. Share your logo or a reference idea to discuss the style, specifications and quote.\n\n**按钮**：Discuss My Logo Sign\n\n**辅助文案**：Not sure about materials or dimensions? Start with what you have.\n\n**Find a Look That Fits Your Space**\n\nCompare front-lit lettering, backlit effects and non-illuminated finishes through selected product examples.\n\n**Made Around Your Logo and Location**\n\nYour artwork, dimensions, mounting surface and lighting preferences help define the sign. Final construction and suitability are reviewed before confirmation.\n\n**A Simple Way to Start**\n\nShare your project → Continue on WhatsApp → Confirm the details → Review your quote\n\n**Do I need a finished design?**\n\nNo final production drawing is required to begin. Share your logo or a reference image for review.\n\n**Can you deliver to my location?**\n\nTell us the destination so we can confirm shipping arrangements.\n\n**Is installation included?**\n\nInstallation scope is confirmed separately for your project. Tell us whether you have a local installer.\n\n**底部标题**：Let’s Explore Your Logo Sign\n\nTell us where it will be used and delivered, then continue on WhatsApp.\n\n**按钮**：Get a Custom Quote", "image": "/assets/office-halo.webp", "imageAlt": "Custom signage concept", "imageKind": "concept", "indexable": false, "sort": 0}','published',0);
INSERT OR IGNORE INTO content_items(id,type,slug,draft_json,published_json,status,sort_order) VALUES('landing-sign-fabrication','landing','sign-fabrication','{"title": "Custom Lettering & Sign Fabrication for Your Next Project", "intro": "Working on a customer sign project? Share your drawings or sourcing requirements for a project-based fabrication and supply quote.", "body": "**按钮**：Discuss My Fabrication Requirements\n\n**Explore Fabrication Options**\n\n- Illuminated letters\n- Backlit lettering\n- Metal dimensional letters\n- Acrylic signs\n- Selected specialty constructions\n\n**Start with the Specification You Have**\n\nSend artwork, dimensions, quantities and destination details. Highlight any finish, electrical, mounting or documentation requirements that must be reviewed.\n\n**Agree the Details Before Production**\n\nConfirm the quoted construction, approval process, packing, shipping and installation responsibilities before the order moves into production.\n\n**底部标题**：Have Drawings or a Project Brief?\n\nStart your enquiry here, then share the files and discuss open details on WhatsApp.\n\n**按钮**：Start a Trade Enquiry", "image": "/assets/craft-details.webp", "imageAlt": "Custom signage concept", "imageKind": "concept", "indexable": false, "sort": 0}','{"title": "Custom Lettering & Sign Fabrication for Your Next Project", "intro": "Working on a customer sign project? Share your drawings or sourcing requirements for a project-based fabrication and supply quote.", "body": "**按钮**：Discuss My Fabrication Requirements\n\n**Explore Fabrication Options**\n\n- Illuminated letters\n- Backlit lettering\n- Metal dimensional letters\n- Acrylic signs\n- Selected specialty constructions\n\n**Start with the Specification You Have**\n\nSend artwork, dimensions, quantities and destination details. Highlight any finish, electrical, mounting or documentation requirements that must be reviewed.\n\n**Agree the Details Before Production**\n\nConfirm the quoted construction, approval process, packing, shipping and installation responsibilities before the order moves into production.\n\n**底部标题**：Have Drawings or a Project Brief?\n\nStart your enquiry here, then share the files and discuss open details on WhatsApp.\n\n**按钮**：Start a Trade Enquiry", "image": "/assets/craft-details.webp", "imageAlt": "Custom signage concept", "imageKind": "concept", "indexable": false, "sort": 0}','published',0);
INSERT OR IGNORE INTO site_settings(id,value_json) VALUES(1,'{"brand": "Custom Sign Forge", "whatsapp": "", "email": "", "businessDescription": "Custom business signs, illuminated letters and dimensional lettering, supplied through our manufacturing partners.", "faq": [["Can I start without final dimensions?", "Yes. Share the intended location and any approximate measurements you have. Final dimensions will need to be confirmed before production."], ["Can you work from my logo?", "Send your logo on WhatsApp so we can review the artwork and discuss how it could be made into a sign."], ["How much will my sign cost?", "Pricing depends on the design, dimensions, materials, lighting, quantity and delivery requirements. We quote after reviewing your project."], ["Can you ship to my country?", "Tell us the destination country and city. We’ll confirm the available shipping arrangements as part of the enquiry."], ["Who handles installation?", "Installation arrangements must be confirmed for your project. Please tell us whether you have a local installer and what support or documentation they require."]]}');